module.exports = {
  tokenize: function(expr) {
    const tokens = [];
    let i = 0;
    while (i < expr.length) {
      if (expr[i] === ' ') {
        i++;
      } else if (expr[i] === '+' || expr[i] === '-' || expr[i] === '*' || expr[i] === '/' || expr[i] === '(' || expr[i] === ')') {
        tokens.push({ type: 'operator', value: expr[i] });
        i++;
      } else {
        let num = '';
        while (i < expr.length && !isNaN(expr[i]) && expr[i] !== ' ') {
          num += expr[i];
          i++;
        }
        tokens.push({ type: 'number', value: parseFloat(num) });
      }
    }
    return tokens;
  },

  evaluate: function(expr) {
    const tokens = this.tokenize(expr);
    let i = 0;

    function parseFactor() {
      if (tokens[i].type === 'number') {
        return tokens[i++].value;
      } else if (tokens[i].type === 'operator' && tokens[i].value === '(') {
        i++;
        const result = parseExpression();
        i++;
        return result;
      } else {
        throw new Error('Malformed expression');
      }
    }

    function parseTerm() {
      let result = parseFactor();
      while (i < tokens.length && (tokens[i].type === 'operator' && (tokens[i].value === '*' || tokens[i].value === '/'))) {
        const operator = tokens[i].value;
        i++;
        const nextFactor = parseFactor();
        if (operator === '*') {
          result *= nextFactor;
        } else if (operator === '/') {
          if (nextFactor === 0) {
            throw new Error('Division by zero');
          }
          result /= nextFactor;
        }
      }
      return result;
    }

    function parseExpression() {
      let result = parseTerm();
      while (i < tokens.length && (tokens[i].type === 'operator' && (tokens[i].value === '+' || tokens[i].value === '-'))) {
        const operator = tokens[i].value;
        i++;
        const nextTerm = parseTerm();
        if (operator === '+') {
          result += nextTerm;
        } else if (operator === '-') {
          result -= nextTerm;
        }
      }
      return result;
    }

    return parseExpression();
  }
};

